import django.db.models.deletion
import django.utils.timezone
from django.db import migrations, models
from django.utils import timezone


def convertir_pedidos(apps, schema_editor):
    """
    Pedidos existentes → nuevo esquema:
    - su descripción/cantidad pasa a ser una partida,
    - el estado DETENIDO se vuelve bandera (el pedido queda EN PROCESO),
    - la fecha de captura se toma de la fecha de creación.
    """
    Pedido = apps.get_model("pedidos", "Pedido")
    PartidaPedido = apps.get_model("pedidos", "PartidaPedido")

    for pedido in Pedido.objects.all():
        PartidaPedido.objects.create(
            pedido=pedido,
            cantidad=max(pedido.cantidad or 1, 1),
            descripcion=(pedido.descripcion or "Sin descripción")[:255],
        )
        if pedido.estado == "DETENIDO":
            pedido.estado = "EN_PROCESO"
            pedido.detenido = True
        pedido.fecha_captura = timezone.localdate(pedido.fecha_creacion)
        pedido.save(update_fields=["estado", "detenido", "fecha_captura"])


